        private static void RunJumpFetchTests(string directory)
        {
            var jump=new JumpGame(7);Check(!jump.Jump()&&jump.State==SnackRoundState.Ready,"Jump runner waits for an explicit round start");jump.Start();Check(jump.Jump()&&!jump.Jump(),"A jump starts once and cannot double-jump in midair");double peak=0;for(int i=0;i<200;i++){jump.Step(.01);peak=Math.Max(peak,jump.Height);if(jump.Grounded)break;}Check(jump.Grounded&&peak>110&&jump.Landing>0,"Jump height clears hurdles and landing triggers a brief squash");
            jump.Start();jump.Jump();for(int i=0;i<20;i++)jump.Step(.01);jump.AddForTest(180,55);for(int i=0;i<30;i++)jump.Step(.01);Check(jump.Cleared==1&&jump.Score==20&&jump.Lives==3,"A real jump clears a hurdle and awards points once");for(int i=0;i<30;i++)jump.Step(.01);Check(jump.Score==20,"A passed hurdle cannot give repeated points");
            jump.Start();jump.AddForTest(180,30,true);jump.Step(.01);Check(jump.Eaten==1&&jump.Score==10&&jump.Items.Count==0,"Runner snacks give ten points and are consumed once");
            jump.AddForTest(180,50);jump.AddForTest(180,50);jump.Step(.01);Check(jump.Lives==2&&jump.Invulnerable>0,"Overlapping hurdles cost only one life during protection");double time=jump.Elapsed,height=jump.Height;jump.Pause();jump.Step(.2);Check(jump.Elapsed==time&&jump.Height==height,"Runner pause freezes both timer and jump physics");jump.Resume();jump.Step(.01);Check(jump.Elapsed>time,"Runner resume continues active time");
            jump.Start();for(int hit=0;hit<3;hit++){if(hit>0)for(int i=0;i<130;i++){jump.ClearForTest();jump.Step(.01);}jump.AddForTest(180,50);jump.Step(.01);}Check(jump.Lives==0&&jump.State==SnackRoundState.Finished&&!jump.Jump(),"The third runner collision ends input and the round");jump.Start();Check(jump.Score==0&&jump.Lives==3&&jump.Items.Count==0&&jump.Grounded,"Runner restart clears old score, objects and airtime");
            var a=new JumpGame(9);var b=new JumpGame(9);a.Start();b.Start();a.Jump();b.Jump();for(int i=0;i<60;i++)a.Step(1.0/30);for(int i=0;i<240;i++)b.Step(1.0/120);Check(Math.Abs(a.Elapsed-b.Elapsed)<.001&&Math.Abs(a.Height-b.Height)<.001&&a.Items.Count==b.Items.Count&&a.Items.Zip(b.Items,(u,v)=>Math.Abs(u.X-v.X)<.001&&u.Height==v.Height).All(v=>v),"Runner motion and spawning agree at thirty and one hundred twenty FPS");
            jump.Start();for(int i=0;i<7200;i++){jump.ClearForTest();jump.Step(1.0/120);}Check(jump.State==SnackRoundState.Finished&&Math.Abs(jump.Elapsed-60)<.001,"The runner has a bounded sixty-second round");jump.Step(double.NaN);Check(!double.IsNaN(jump.Height),"Invalid runner frame time cannot corrupt the character");
            string scorePath=Path.Combine(directory,"jump-best","scores.json");var records=new GameRecords(scorePath);records.Record("snack",60);records.Record("jump",100);records.Record("jump",20);var restored=new GameRecords(scorePath);Check(restored.Best("jump")==100&&restored.Best("snack")==60&&restored.Plays("jump")==2,"Jump best scores persist alongside the three existing games");
            var area=new RectangleF(0,0,1200,800);var range=new RectangleF(80,60,1040,680);var home=new PointF(1000,650);var fetch=new FetchGame(area,range,home);fetch.Step(.1,home);Check(fetch.Phase==FetchPhase.Waiting&&fetch.Movement==PointF.Empty,"Desktop fetch starts with a parked ball and waits for the user");
            var pointer=new PointF(fetch.Ball.Position.X+5,fetch.Ball.Position.Y+6);var initial=fetch.Ball.Position;fetch.BeginDrag(pointer,0);fetch.Drag(pointer,.01);fetch.Step(.01,home);Check(fetch.Ball.Position==initial&&fetch.Ball.Held,"Grabbing a ball off center does not make it jump to the pointer");fetch.Drag(new PointF(pointer.X-300,pointer.Y-140),.06);fetch.Step(.05,home);fetch.Release(new PointF(pointer.X-300,pointer.Y-140),.065);Check(fetch.Phase==FetchPhase.Chasing&&fetch.Ball.Flying&&fetch.Ball.Velocity.X<0,"Flicking the ball launches it and starts pet pursuit");
            PointF pet=home;bool carried=false,cheered=false;for(int i=0;i<3000;i++){fetch.Step(.01,pet);pet=new PointF(pet.X+fetch.Movement.X,pet.Y+fetch.Movement.Y);carried|=fetch.Carrying;cheered|=fetch.Phase==FetchPhase.Cheering;var p=fetch.Ball.Position;var bounds=fetch.Ball.Bounds;if(p.X<bounds.Left-.1||p.X>bounds.Right+.1||p.Y<bounds.Top-.1||p.Y>bounds.Bottom+.1)throw new Exception("Fetch ball escaped its working area");if(cheered&&fetch.Phase==FetchPhase.Waiting)break;}
            Check(carried&&cheered&&fetch.Phase==FetchPhase.Waiting&&Math.Abs(pet.X-home.X)<9&&Math.Abs(pet.Y-home.Y)<9,"Sangmon catches the ball, carries it home and gets ready to play again");
            var corner=new FetchGame(area,range,home);corner.Ball.Place(new PointF(corner.Ball.Bounds.Right,corner.Ball.Bounds.Bottom));corner.BeginDrag(corner.Ball.Position,0);corner.Release(corner.Ball.Position,1);corner.Step(.01,new PointF(range.Right,range.Bottom));Check(corner.Carrying,"A ball resting in a screen corner remains reachable by the pet");
            fetch.BeginDrag(fetch.Ball.Position,4);fetch.CancelDrag();Check(!fetch.Ball.Held&&fetch.Phase==FetchPhase.Waiting&&fetch.Ball.Velocity==PointF.Empty,"Lost ball capture does not create a phantom throw or chase");
            fetch.BeginDrag(new PointF(float.NaN,0),5);Check(!fetch.Ball.Held,"Invalid ball pointer data is ignored");fetch.BeginDrag(fetch.Ball.Position,6);fetch.Release(fetch.Ball.Position,7);Check(fetch.Ball.Flying&&fetch.Ball.Velocity==PointF.Empty,"A gently released toy falls naturally instead of hanging in the air");
            fetch.Resize(new RectangleF(-1600,-900,1000,700),new RectangleF(-1520,-840,840,580));fetch.Step(.02,new PointF(-800,-400));Check(fetch.Ball.Position.X<0&&fetch.Ball.Position.Y<0,"Fetch bounds support a display left or above the primary monitor");
            fetch.Resize(new RectangleF(5,8,0,0),new RectangleF(5,8,0,0));fetch.Step(.1,new PointF(5,8));Check(!float.IsNaN(fetch.Ball.Position.X)&&fetch.Ball.Position.X==5,"A changing or collapsed fetch area remains finite and bounded");fetch.Stop();var stopped=fetch.Ball.Position;fetch.Step(.1,home);Check(!fetch.Active&&fetch.Movement==PointF.Empty&&fetch.Ball.Position==stopped,"Ending fetch stops ball and pursuit immediately");
            var ball=new PetDynamics();ball.SetBounds(new RectangleF(0,0,1000,1000));ball.Place(new PointF(500,200));ball.StartFlight(new PointF(10000,0));Check(ball.Velocity.X<=PetDynamics.MaxThrowSpeed,"Toy launches share the bounded desktop throw speed");ball.Step(.1);Check(ball.Position.Y>200,"A thrown toy uses the existing desktop gravity");
        }
        public static void JumpFetchPreview(string directory)
        {
            Directory.CreateDirectory(directory);var records=new GameRecords();
            using(var hub=new GameHubWindow(records)){hub.Show();Application.DoEvents();hub.VerifyCardsForTest();using(var image=new Bitmap(hub.Width,hub.Height)){hub.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-playroom-four.png"));}hub.ClientSize=Design.Size(740,560);Application.DoEvents();hub.VerifyCardsForTest();using(var image=new Bitmap(hub.Width,hub.Height)){hub.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-playroom-four-compact.png"));}hub.Close();}
            using(var window=new JumpGameWindow(records)){
                window.Show();Application.DoEvents();window.StartRound();var e=window.NativeKeyDownForTest(Keys.Up);if(!e.Handled||e.SuppressKeyPress)throw new Exception("Native jump key release is suppressed");for(int i=0;i<90;i++)window.Advance(.01);window.NativeKeyDownForTest(Keys.Up);if(!window.Game.Grounded)throw new Exception("Held jump auto-repeats on landing");window.NativeKeyUpForTest(Keys.Up);window.NativeKeyDownForTest(Keys.Up);window.NativeKeyUpForTest(Keys.Up);for(int i=0;i<19;i++)window.Advance(.01);window.Game.ClearForTest();window.Game.AddForTest(410,54);window.Game.AddForTest(225,125,true);window.SavePreview(Path.Combine(directory,"windows-jump.png"));window.PauseRound();double age=window.Game.Elapsed;window.Advance(.2);if(age!=window.Game.Elapsed)throw new Exception("Native runner pause failed");window.TogglePause();for(int i=0;i<100;i++)window.Advance(.01);window.Game.ClearForTest();window.PointerForTest();if(window.Game.Grounded)throw new Exception("Native runner mouse jump failed");
                window.StartRound();window.Game.AddForTest(180,30,true);window.Advance(.01);for(int i=0;i<7200&&window.Game.State==SnackRoundState.Playing;i++){window.Game.ClearForTest();window.Advance(1.0/120);}window.Advance(.1);if(records.Best("jump")!=10||records.Plays("jump")!=1)throw new Exception("Runner result was not saved exactly once");window.SavePreview(Path.Combine(directory,"windows-jump-result.png"));window.Close();
            }
            int opened=0;FetchGame old;DesktopBallWindow oldToy;
            using(var pet=new DesktopPet(delegate{opened++;})){
                pet.StartFetchForTest();old=pet.Fetch;oldToy=pet.Toy;
                using(var frame=oldToy.MakeFrame()){if(frame.GetPixel(0,0).A!=0||frame.GetPixel(frame.Width/2,frame.Height/2).A==0)throw new Exception("Desktop ball transparency failed");LayeredWindow.Update(oldToy.Handle,frame,new Point(-30000,-30000));frame.Save(Path.Combine(directory,"windows-fetch-ball.png"));}
                var pointer=old.Ball.Position;oldToy.BeginPointer(pointer,0);oldToy.MovePointer(new PointF(pointer.X-150,pointer.Y-80),.05);pet.StepMotion(.05,false);oldToy.EndPointer(new PointF(pointer.X-150,pointer.Y-80),.055);if(old.Phase!=FetchPhase.Chasing)throw new Exception("Native ball pointer release did not start fetch");bool carried=false,cheered=false;for(int i=0;i<3000;i++){pet.StepMotion(.01,true);carried|=old.Carrying;cheered|=old.Phase==FetchPhase.Cheering;if(cheered&&old.Phase==FetchPhase.Waiting)break;}if(!carried||!cheered||old.Phase!=FetchPhase.Waiting)throw new Exception("Native pet movement/hover prevented fetching and returning");pet.BeginPointer(pet.Location,1);if(pet.FetchPlaying||old.Active||!oldToy.IsDisposed||opened!=0)throw new Exception("Manual pet grab did not safely end fetch");pet.CancelPointer();
                pet.StartFetchForTest();old=pet.Fetch;oldToy=pet.Toy;pet.Location=new Point(-30000,-30000);pet.Show();pet.Hide();if(pet.FetchPlaying||old.Active||!oldToy.IsDisposed)throw new Exception("Hiding the pet left an orphaned toy");
            }
            var area=new RectangleF(0,58,960,480);var range=new RectangleF(80,120,800,350);var fetch=new FetchGame(area,range,new PointF(740,410));var p=fetch.Ball.Position;fetch.BeginDrag(p,0);fetch.Drag(new PointF(260,440),.05);fetch.Step(.05,fetch.Home);fetch.Release(new PointF(260,440),.055);PointF center=fetch.Home;for(int i=0;i<25;i++){fetch.Step(.02,center);center=new PointF(center.X+fetch.Movement.X,center.Y+fetch.Movement.Y);}
            using(var image=new Bitmap(960,600))using(var g=Graphics.FromImage(image))using(var toy=new DesktopBallWindow(fetch,delegate{})){g.Clear(Color.FromArgb(246,245,239));MiniGameArt.Text(g,"바탕화면 공놀이",24,Design.Ink,30,13,true);using(var border=new Pen(Color.FromArgb(208,214,194),2))g.DrawRectangle(border,1,58,957,479);MiniGameArt.Pet(g,center.X,center.Y,208,.5f);using(var frame=toy.MakeFrame())g.DrawImageUnscaled(frame,(int)fetch.Ball.Position.X-32,(int)fetch.Ball.Position.Y-32);MiniGameArt.Text(g,"공을 던지면 따라가서 가져와요 · 그림은 재현 가능한 테스트 장면",11,Design.Muted,30,562);image.Save(Path.Combine(directory,"windows-fetch-demo.png"));}
            Console.WriteLine("Native jump/fetch: four-card hub, keyboard/mouse jump, pause, single score save, ball alpha/native rendering, throw routing, manual pet override and hide cleanup passed.");
        }
    }
